package com.juanvargas.kubesynapse.domain.model;

import lombok.Builder;
import lombok.Value;

import java.time.Instant;
import java.util.List;

/**
 * Immutable diagnostic report generated by KubeSynapse.
 * Implements the Builder pattern for clean, type-safe construction.
 */
@Value
@Builder
public class DiagnosticReport {
    String incidentId;
    String namespace;
    String podName;
    DiagnosticSeverity severity;
    String rootCause;
    String technicalDetails;
    String aiRecommendation;
    List<String> suggestedRemediations;
    List<String> pipelineTrail;
    Instant analyzedAt;
}
